-- Reference/demo data exported from the project database.
-- COPY first targets temporary staging tables so this migration is safe on an existing development database.

CREATE TEMP TABLE seed_map_feature ON COMMIT DROP AS
SELECT * FROM public.map_feature WITH NO DATA;


SELECT id, layer_id, source_feature_id, name, properties, geom_local, created_at, updated_at
FROM seed_map_feature
ON CONFLICT (id) DO NOTHING;

DO $verify$
BEGIN
    IF EXISTS (
        SELECT id FROM seed_map_feature
        EXCEPT
        SELECT id FROM public.map_feature
    ) THEN
        RAISE EXCEPTION 'Failed to merge all seed rows into public.map_feature';
    END IF;
END
$verify$;

SELECT setval(
    pg_get_serial_sequence('public.map_feature', 'id'),
    COALESCE((SELECT max(id) FROM public.map_feature), 1),
    EXISTS (SELECT 1 FROM public.map_feature)
);

ANALYZE public.map_feature;
